-- public.remove_planned_visit(p_visit_id uuid, p_reason text, p_idempotency_key uuid)
CREATE OR REPLACE FUNCTION public.remove_planned_visit(p_visit_id uuid, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid := (select auth.uid());
  v   public.care_visits%rowtype;
  why text := private.check_text(p_reason, 3, 300, 'reason');
begin
  if uid is null then
    return jsonb_build_object('result', 'rejected', 'reason', 'not_team_member');
  end if;
  if private.begin_command('remove_planned_visit', p_idempotency_key) then
    perform private.end_command('duplicate');
    return jsonb_build_object('result', 'duplicate');
  end if;

  select * into v from public.care_visits where id = p_visit_id for update;
  -- BK-E1B-M (CGR-249): a visit written from a take is never deleted by a person command.
  if found and v.order_take_id is not null
     and private.is_org_member(v.organization_id) and private.is_team_member(v.team_id) then
    perform private.write_visit_refusal(v, 'remove_planned_visit', 'take_visit');  -- BK-E1B-R (CGR-252): one row
    perform private.end_command('take_visit');
    return jsonb_build_object('result', 'take_visit');
  end if;
  if not found or v.status <> 'planned'
     or not private.is_org_member(v.organization_id) or not private.is_team_member(v.team_id)
     or exists (select 1 from public.visit_events e where e.visit_id = v.id)
     or exists (select 1 from public.visit_observations o where o.visit_id = v.id)
     or exists (select 1 from public.care_notes n where n.visit_id = v.id)
     or exists (select 1 from public.quality_events q where q.visit_id = v.id) then
    perform private.end_command('rejected');
    return jsonb_build_object('result', 'rejected', 'reason', 'not_removable');
  end if;

  insert into public.visit_plan_changes (organization_id, visit_id, case_id, team_id, change, before, reason, actor_id)
  values (v.organization_id, v.id, v.case_id, v.team_id, 'removed', private.visit_slot_json(v), why, uid);
  delete from public.care_visits where id = v.id;

  perform private.end_command('ok');
  return jsonb_build_object('result', 'ok', 'visit_id', v.id);
end;
$function$;

revoke all on function public.remove_planned_visit(p_visit_id uuid, p_reason text, p_idempotency_key uuid) from public, anon, authenticated, service_role;
grant execute on function public.remove_planned_visit(p_visit_id uuid, p_reason text, p_idempotency_key uuid) to authenticated;
grant execute on function public.remove_planned_visit(p_visit_id uuid, p_reason text, p_idempotency_key uuid) to service_role;
comment on function public.remove_planned_visit(p_visit_id uuid, p_reason text, p_idempotency_key uuid) is 'BK-e1b / CGR-249: a visit written from a take (order_take_id) is refused with take_visit; the way out is the release (CGR-242). BK-e1b / CGR-252: a take_visit refusal writes one audit row (outcome take_visit, no key).';
